mapper.select:
SELECT ACCID, QCMD, QCMC, BQMD, BQMC, QMMD, QMMC, FNAME, QCMD_F, QCMC_F, BQMD_F, BQMC_F, QMMD_F, QMMC_F, NUM, AYEAR, AMONTH, LJMD, LJMC, LJMD_F,LJMC_F, QCDC, QMDC FROM ${dbSource}.TBL_ACC_SUM WHERE 1=1
AND AYEAR = #{strYear}
AND AMONTH = #{strMonth}
AND ACCID in
${item}

mapper.update:
update ${dbSource}.TBL_ACC_REPORT_YBAL set
QCS1 = #{qcs1,jdbcType=VARCHAR},QMS1 = #{qms1,jdbcType=VARCHAR},
QCS2 = #{qcs2,jdbcType=VARCHAR}, QMS2 = #{qms2,jdbcType=VARCHAR}
where zid = #{zid}

update ${dbSource}.TBL_ACC_REPORT_MPROFIT
set CURYEAR_BNLJ = #{curyearBnlj,jdbcType=VARCHAR},
    CURYEAR_BYS  = #{curyearBys,jdbcType=VARCHAR}
where ID = #{id}
